  { id: 'o-3', customerId: 'c-1', total: 45 },
  { id: 'o-4', customerId: 'c-3', total: 200 },
];

export function listOrders(offset: number, limit: number): Order[] {
  return ORDERS.slice(offset, offset + limit);
}

