import { err, ok, type Result } from '../kernel/result.js';
import type { AppError } from '../kernel/errors.js';
import { lookupOrder } from './order.service.js';

const refundedOrderIds = new Set<string>();

export function refundOrder(orderId: string): Result<{ refunded: true }, AppError> {
  const order = lookupOrder(orderId);

  if (!order) {
    return err({ code: 'NOT_FOUND', message: `Order ${orderId} not found` });
  }

  if (refundedOrderIds.has(orderId)) {
    return err({ code: 'ALREADY_REFUNDED', message: `Order ${orderId} has already been refunded` });
  }

  if (order.total < 10) {
    return err({ code: 'INSUFFICIENT_AMOUNT', message: `Order ${orderId} total must be at least 10 to refund` });
  }

  refundedOrderIds.add(orderId);
  return ok({ refunded: true });
}

